async function fetchStandaloneHtml() {
	const res = await fetch("/hugex-standalone.html");
	if (!res.ok) throw new Error("Standalone HTML şablonu yüklenemedi.");
	return res.text();
}
async function downloadStandaloneHtmlFile() {
	const html = await fetchStandaloneHtml();
	const blob = new Blob([html], { type: "text/html;charset=utf-8" });
	const url = URL.createObjectURL(blob);
	const a = document.createElement("a");
	a.href = url;
	a.download = "HUGEX-Siparis-Uretim.html";
	document.body.appendChild(a);
	a.click();
	a.remove();
	URL.revokeObjectURL(url);
}
async function downloadPcAppZip() {
	const res = await fetch("/hugex-pc-uygulama.zip", { cache: "no-store" });
	if (!res.ok) throw new Error("PC ZIP paketi sunucudan alınamadı.");
	if ((res.headers.get("content-type") || "").includes("text/html")) throw new Error("PC ZIP paketi henüz hazır değil.");
	const blob = await res.blob();
	const url = URL.createObjectURL(blob);
	const a = document.createElement("a");
	a.href = url;
	a.download = "HUGEX-Siparis-Uretim-PC.zip";
	document.body.appendChild(a);
	a.click();
	a.remove();
	URL.revokeObjectURL(url);
}
