function loadInitialUnits() {
	const stored = safeReadArray(STORAGE_UNITS_KEY, null);
	if (!stored || stored.length === 0) {
		const initial = JSON.parse(JSON.stringify(DEFAULT_UNITS));
		try {
			localStorage.setItem(STORAGE_UNITS_KEY, JSON.stringify(initial));
		} catch {}
		return initial;
	}
	return stored;
}
function loadInitialOrders() {
	const stored = safeReadArray(STORAGE_ORDERS_KEY, null);
	if (!stored) {
		const initial = createSampleOrders();
		try {
			localStorage.setItem(STORAGE_ORDERS_KEY, JSON.stringify(initial));
		} catch {}
		return initial;
	}
	return stored;
}
function syncOrderStatusFromUnits(ord) {
	const total = ord.unitConfigs.length;
	const done = ord.unitConfigs.filter((x) => x.status === "Tamamlandı").length;
	const inProg = ord.unitConfigs.some((x) => x.status === "İşlemde" || x.status === "Tamamlandı");
	let status = "Hazırlandı";
	if (total > 0 && done === total) status = "Tamamlandı";
	else if (inProg) status = "Üretimde";
	return {
		...ord,
		status
	};
}
